update public.program_catalog_ca_staging set official_program_url=case id when 3045 then 'https://langara.ca/programs-courses/environmental-studies-associate-science-degree' when 3059 then 'https://langara.ca/programs-courses/environmental-studies-associate-arts-degree' else official_program_url end,source_status='suspended_admissions_from_fall_2026_until_further_notice',source_as_of=date '2026-08-08' where id in (3045,3059) and institution_name='Langara College';
update public.program_pgwp_ca_staging p set international_program_admission_status='international_admissions_suspended_from_fall_2026_until_further_notice',source_url=case p.program_catalog_id when 3045 then 'https://langara.ca/programs-courses/environmental-studies-associate-science-degree/admissions' when 3059 then 'https://langara.ca/programs-courses/environmental-studies-associate-arts-degree' else p.source_url end,source_as_of=date '2026-08-08',verified_at=now(),rule_notes=concat_ws(' ',nullif(p.rule_notes,''),'Langara current Environmental Studies page checked 2026-08-08: applications for this associate-degree variant are suspended from the Fall 2026 intake until further notice.') where p.program_catalog_id in (3045,3059);
update public.program_catalog_ca_staging set official_program_url='https://langara.ca/programs-courses/environmental-studies-diploma-arts-and-science',source_status='official_program_page_verified_international_apply_current_2026_27',source_as_of=date '2026-08-08' where id=3067 and institution_name='Langara College';
