update public.program_catalog_ca_staging set official_program_url=case id when 4012 then 'https://www.selkirk.ca/programs/environment-geomatics/applied-environmental-science-and-planning-technology-diploma' when 4083 then 'https://www.selkirk.ca/programs/health-human-services/social-work-certificate' when 4084 then 'https://www.selkirk.ca/programs/health-human-services/social-work-diploma' else official_program_url end,source_status='official_program_page_verified_current_2026_27',source_as_of=date '2026-08-08' where id in (4012,4083,4084) and institution_name='Selkirk College';
